            result.append((color, cells))
    return result


def _normalized(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r - r0, c - c0) for r, c in cells)


def _l_frame(cells):
    """Find a filled, one-cell-wide L made of two straight arms."""
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    for cr in (r0, r1):
        for cc in (c0, c1):
            dr = 1 if cr == r0 else -1
            dc = 1 if cc == c0 else -1
            vertical = {(cr + dr * i, cc) for i in range(r1 - r0 + 1)}
            horizontal = {(cr, cc + dc * i) for i in range(c1 - c0 + 1)}
            if len(vertical) >= 3 and len(horizontal) >= 3 and cells == vertical | horizontal:
                return cr, cc, dr, dc
